/* Repaire Rocket de Céladopole (Kanto) : sol, dalles flèches, blocs X, murs, cartons, chaise, frigo et bureau de Giovanni découpés dans les captures Let's Go Pikachu / Évoli envoyées par Raphaël (voir CREDITS.md) */
const LG = { img:null, R:{"office":[0,0,868,239],"gdesk":[0,241,478,177],"xblk":[480,241,104,114],"floor":[586,241,104,104],"right":[692,241,104,104],"down":[798,241,104,104],"chair":[904,241,69,86],"fridge":[975,241,101,85],"boxroll":[0,420,89,84],"boxes":[91,420,82,82],"stop":[175,420,104,58],"cap":[281,420,64,38],"red":[347,420,14,10],"band":[363,420,104,8],"wall":[0,506,1054,112]}, K:.5, floor:null };
(() => { const im = new Image(); im.onload = () => { LG.img = im; LG.floor = null; for (const c of chunkData.values()) c.canvas = null; }; im.src = "data:image/webp;base64,"; })();
const rocketLG = () => LEVEL.rocket && !LEVEL.acajou && LG.img;
const LG_OFFICE = { x:0, y:START_Y - 330 }; // bureau de Giovanni, juste au nord du départ
function lgSpr(g, n, x, y, k = 1, fx = false, fy = false) { // dessine la pièce n, coin haut gauche en (x, y), taille du jeu × k
  const r = LG.R[n], w = r[2] * LG.K * k, h = r[3] * LG.K * k;
  if (!fx && !fy) return g.drawImage(LG.img, r[0], r[1], r[2], r[3], x, y, w, h);
  g.save(); g.translate(x + (fx ? w : 0), y + (fy ? h : 0)); g.scale(fx ? -1 : 1, fy ? -1 : 1); g.drawImage(LG.img, r[0], r[1], r[2], r[3], 0, 0, w, h); g.restore();
}
function lgFloor(g) { // carreau de 4 × 4 dalles : joints épais en haut et à gauche, croix rouges aux coins
  const c = document.createElement("canvas"); c.width = c.height = 416; const x = c.getContext("2d"), A = LG.img, R = LG.R;
  for (let j = 0; j < 4; j++) for (let i = 0; i < 4; i++) x.drawImage(A, ...R.floor, i * 104, j * 104, 104, 104);
  for (let i = 0; i < 4; i++) x.drawImage(A, ...R.band, i * 104, -2, 104, 8);
  x.save(); x.rotate(Math.PI / 2); for (let i = 0; i < 4; i++) x.drawImage(A, ...R.band, i * 104, -6, 104, 8); x.restore();
  for (const [px, py] of [[104, 104], [312, 312], [312, 104]]) x.drawImage(A, ...R.red, px - 7, py - 5, 14, 10);
  const p = g.createPattern(c, "repeat"); p.setTransform(new DOMMatrix().scale(.5)); return p;
}
function lgWall(g, x, yb, w, ph, deep) { // pan de mur blanc à bande rouge, dessus gris clair, bas posé en yb
  const r = LG.R.wall, K = LG.K, FH = r[3] * K, top = yb - FH - deep;
  g.fillStyle = "rgba(0,0,0,.28)"; g.fillRect(x + 4, yb, w, 10);
  const cap = LG.R.cap; g.drawImage(LG.img, cap[0] + 4, cap[1] + 4, cap[2] - 8, cap[3] - 8, x, top, w, deep);
  g.fillStyle = "rgba(255,255,255,.35)"; g.fillRect(x, top, w, 2); g.fillStyle = "rgba(0,0,0,.18)"; g.fillRect(x, top, 2, deep); g.fillRect(x + w - 2, top, 2, deep);
  let dx = 0, sx = Math.floor(ph * 97) % (r[2] - 200);
  while (dx < w) { const sw = Math.min(r[2] - sx, (w - dx) / K); g.drawImage(LG.img, r[0] + sx, r[1], sw, r[3], x + dx, yb - FH, sw * K, FH); dx += sw * K; sx = 0; }
}
function renderRocketLG(ci, cj) {
  const c = getChunk(ci, cj), x0 = ci * CH, y0 = cj * CH, K = LG.K;
  const cv2 = document.createElement("canvas"); cv2.width = cv2.height = CH * CH_SCALE;
  const g = cv2.getContext("2d"); g.scale(CH_SCALE, CH_SCALE); g.translate(-x0, -y0); g.imageSmoothingEnabled = true;
  if (!LG.floor) LG.floor = lgFloor(g);
  g.fillStyle = LG.floor; g.fillRect(x0, y0, CH, CH);
  { g.globalCompositeOperation = "lighter"; // halos des néons du plafond
    for (let a = -1; a <= 1; a++) for (let b2 = -1; b2 <= 1; b2++) for (const l of getChunk(ci + a, cj + b2).lamps || []) {
      const lg = g.createRadialGradient(l.x, l.y, 0, l.x, l.y, l.r); lg.addColorStop(0, "rgba(255,250,240,.08)"); lg.addColorStop(1, "rgba(255,250,240,0)"); g.fillStyle = lg; g.fillRect(l.x - l.r, l.y - l.r, l.r * 2, l.r * 2); }
    g.globalCompositeOperation = "source-over"; }
  const all = { crates:[], machines:[], spinners:[], stops:[], props:[], cages:[], office:[] };
  for (let a = -1; a <= 1; a++) for (let b2 = -1; b2 <= 1; b2++) { const n = getChunk(ci + a, cj + b2); for (const k in all) all[k].push(...(n[k] || [])); }
  for (const sp of all.spinners) lgSpr(g, sp.dy ? "down" : "right", sp.x - 26, sp.y - 26, 1, sp.dx < 0, sp.dy < 0);
  for (const q of all.stops) lgSpr(g, "stop", q.x - 26, q.y - 15);
  const items = [];
  for (const m of all.machines) items.push([m.y + m.h / 2, () => {
    const x = Math.round(m.x - m.w / 2), yb = Math.round(m.y + m.h / 2); lgWall(g, x, yb, m.w, m.ph, Math.round(m.h * .55));
    if (m.v) { const r = LG.R.fridge; lgSpr(g, "fridge", x + m.w * (.2 + (m.ph % 1) * .4), yb + 4 - r[3] * K); }
  }]);
  for (const q of all.props) items.push([q.y + 16, () => {
    if (q.kind === "shelf") { ell(g, q.x, q.y + 14, 44, 8, "rgba(0,0,0,.25)"); lgSpr(g, "chair", q.x - 40, q.y + 16 - LG.R.chair[3] * K); lgSpr(g, "boxroll", q.x + 2, q.y + 18 - LG.R.boxroll[3] * K); }
    else for (const b of q.bs) { ell(g, b.x, b.y + 12, 18, 5, "rgba(0,0,0,.25)"); lgSpr(g, "boxes", b.x - 16, b.y + 14 - LG.R.boxes[3] * K * .8, .8); }
  }]);
  for (const q of all.crates) items.push([q.y + 18, () => {
    if (q.n > 1) { ell(g, q.x, q.y + 18, 30, 7, "rgba(0,0,0,.3)"); lgSpr(g, "xblk", q.x - 26, q.y + 20 - LG.R.xblk[3] * K); }
    else { const n = q.ph < .5 ? "boxes" : "boxroll"; ell(g, q.x, q.y + 16, 20, 6, "rgba(0,0,0,.22)"); lgSpr(g, n, q.x - LG.R[n][2] * K / 2, q.y + 18 - LG.R[n][3] * K); }
  }]);
  for (const q of all.cages) items.push([q.y, () => rkCage(g, q)]);
  for (const o of all.office) {
    items.push([o.y, () => { const r = LG.R.office; g.fillStyle = "rgba(0,0,0,.3)"; g.fillRect(o.x - r[2] * K / 2 + 6, o.y - 8, r[2] * K - 12, 12); lgSpr(g, "office", o.x - r[2] * K / 2, o.y + 6 - r[3] * K); }]);
    items.push([o.y + 96, () => { const r = LG.R.gdesk; ell(g, o.x, o.y + 92, 118, 12, "rgba(0,0,0,.3)"); lgSpr(g, "gdesk", o.x - r[2] * K / 2, o.y + 96 - r[3] * K); }]);
  }
  items.sort((a, b) => a[0] - b[0]); for (const it of items) it[1]();
  c.canvas = cv2; return cv2;
}
